pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 depositAmount, uint256 otherDeposit) public {
        vm.assume(caller != address(0) && caller != other && other != address(0));
        depositAmount = bound(depositAmount, 0, 100 ether);
        otherDeposit = bound(otherDeposit, 0, 100 ether);

        // Give both addresses some ether
        vm.deal(caller, depositAmount);
        vm.deal(other, otherDeposit);

        // caller deposits his ether
        vm.prank(caller);
        (bool successDeposit1,) = address(c).call{value: depositAmount}("");
        require(successDeposit1);

        // other deposits his ether
        vm.prank(other);
        (bool successDeposit2,) = address(c).call{value: otherDeposit}("");
        require(successDeposit2);

        // Record other's balance before withdraw
        uint256 otherBalanceBefore = c.balances(other);

        // caller tries to withdraw
        vm.prank(caller);
        (bool withdrawSuccess,) = address(c).call(abi.encodeWithSelector(c.withdraw.selector));

        // Rule: if withdraw succeeds, other's balance must stay the same
        assertTrue(!withdrawSuccess || c.balances(other) == otherBalanceBefore);
