pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // No fuzz params needed — property must hold for any state reachable via public surface.
        // We'll directly test the invariant: after withdraw, caller's balance is zero and
        // the caller's ETH balance increased by exactly the amount that was in c.balances before.
        address alice = address(0x1234);
        uint256 depositAmount = 1 ether;
        vm.deal(alice, depositAmount);
        vm.prank(alice);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint256 aliceBalanceBefore = c.balances(alice);
        require(aliceBalanceBefore == depositAmount, "precondition: balance recorded");

        uint256 ethBefore = alice.balance;
        vm.prank(alice);
        c.withdraw();

        // General rule: after withdraw, caller's recorded balance is zero
        assertTrue(c.balances(alice) == 0, "caller's balance should be zero after withdraw");
        // and caller's ETH increased by exactly the original balance
        assertTrue(alice.balance == ethBefore + aliceBalanceBefore, "caller must receive full balance");
    }
}

