pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 sendAmount, address other, uint256 otherBalance) public {
        // Restrict inputs to reasonable values
        vm.assume(sender != address(0));
        vm.assume(other != address(0));
        vm.assume(sender != other);
        sendAmount = bound(sendAmount, 0, 1e18);
        otherBalance = bound(otherBalance, 0, 1e18);

        // Setup: give ether to `other` via fallback
        vm.deal(other, otherBalance);
        vm.prank(other);
        (bool successOther, ) = address(c).call{value: otherBalance}("");
        require(successOther);

        // Setup: give ether to `sender` via fallback
        vm.deal(sender, sendAmount);
        vm.prank(sender);
        (bool successSender, ) = address(c).call{value: sendAmount}("");
        require(successSender);

        // Compute expected total ether in contract: initial (0) + sent amounts
        // After withdraw, the caller's balance is zeroed and ether is sent out

        // Perform withdraw by `sender`
        vm.prank(sender);
        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // The rule: after withdraw, the contract's ether balance equals the sum of all user balances
        // plus any leftover (none here, since we only add via fallback and subtract via withdraw)
        uint256 contractBalance = address(c).balance;

        // Sum all balances (we only have two users, but we check the getters for those addresses)
        uint256 senderBalance = c.balances(sender);
        uint256 otherBalanceAfter = c.balances(other);
        uint256 totalUserBalances = senderBalance + otherBalanceAfter;

        // General invariant: contract balance == total user balances
        assertTrue(contractBalance == totalUserBalances);
    }
}

